"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[973],{6973:(e,l,a)=>{a.r(l),a.d(l,{grammarRu:()=>t});let t={1:{title:"Базовый порядок слов SVO",explanation:"В китайском языке используется порядок \xabПодлежащее + Сказуемое + Дополнение\xbb, как в английском.",examples:["Я ем.","Он пьёт воду.","Она читает."]},2:{title:"Связка 是 между существительными",explanation:"是 (sh\xec) связывает два существительных, как \xabэто\xbb или \xabявляется\xbb в русском.",examples:["Я студент.","Он учитель.","Это моя книга."]},3:{title:"Прилагательное-сказуемое с 很",explanation:"В китайском прилагательные выступают сказуемыми напрямую. 很 часто добавляется перед прилагательным, даже если не подразумевается \xabочень\xbb.",examples:["У меня всё хорошо.","Сегодня холодно.","Китайская еда вкусная."]},4:{title:"Обладание с 有",explanation:"有 (yǒu) выражает обладание, как \xabиметь\xbb в русском.",examples:["У меня есть друг.","У него двое детей.","У тебя есть деньги?"]},5:{title:"Наличие с 有",explanation:"有 также выражает наличие — \xabесть\xbb, \xabимеется\xbb что-то в каком-то месте.",examples:["На столе лежит книга.","В школе много учеников."]},6:{title:"Выделение деталей с 是…的",explanation:"Используется для выделения времени, места, способа или участника уже известного/совершённого действия.",examples:["Когда ты приехал?","Я прилетел на самолёте.","Он учил китайский в Пекине."]},7:{title:"Соединение существительных с 和",explanation:"和 (h\xe9) соединяет два существительных, как \xabи\xbb. Не используется для соединения глаголов или предложений.",examples:["я и ты","Папа и мама оба учителя.","Яблоки и вода на столе."]},8:{title:"Определение с 的",explanation:"的 (de) обозначает принадлежность или определяет существительное прилагательным, фразой или придаточным.",examples:["моя книга","красивая девушка","Иероглифы, которые он пишет, очень красивые."]},9:{title:"Отрицание с 不",explanation:"不 (b\xf9) отрицает глаголы и прилагательные в настоящем или будущем времени. Не используется для прошедших действий.",examples:["Я не пью кофе.","Она несчастлива.","Я не китаец."]},10:{title:"Отрицание 有 с помощью 没",explanation:"有 всегда отрицается с 没, никогда с 不. 没有 означает \xabне иметь\xbb или \xabнет\xbb.",examples:["У меня нет денег.","Здесь никого нет."]},11:{title:"Отрицание прошлых действий с 没有",explanation:"没(有) отрицает совершённые действия — что-то не произошло в прошлом.",examples:["Я не ходил.","Он не завтракал.","Она не пришла на урок."]},12:{title:"\xabНе очень\xbb с 不太",explanation:"不太 смягчает отрицание — \xabне очень\xbb, \xabне особо\xbb.",examples:["Мне не очень нравится.","Он не очень доволен."]},13:{title:"\xabБольше не\xbb с 不…了",explanation:"Выражает изменение состояния — что-то больше не имеет места или не будет происходить.",examples:["Я больше не ем.","Он больше не пьёт."]},14:{title:"Вопрос \xabда/нет\xbb с 吗",explanation:"Добавьте 吗 (ma) в конец утверждения, чтобы превратить его в вопрос \xabда/нет\xbb.",examples:["Вы учитель?","Тебе нравится китайская еда?","Он пришёл?"]},15:{title:"Вопрос \xabчто\xbb с 什么",explanation:"什么 (sh\xe9nme) означает \xabчто\xbb. Ставится на место ответа в предложении.",examples:["Как тебя зовут?","Что ты хочешь поесть?","Что это?"]},16:{title:"Вопрос \xabкто\xbb с 谁",explanation:"谁 (sh\xe9i) означает \xabкто\xbb. Заменяет человека в предложении.",examples:["Кто он?","Кто пришёл?"]},17:{title:"Вопрос \xabгде\xbb с 哪儿/哪里",explanation:"哪儿 (nǎr) или 哪里 (nǎlǐ) означает \xabгде\xbb.",examples:["Где ты живёшь?","Где больница?"]},18:{title:"Вопрос \xabкогда\xbb с 什么时候",explanation:"什么时候 (sh\xe9nme sh\xedh\xf2u) означает \xabкогда\xbb.",examples:["Когда ты придёшь?","Когда мы будем есть?"]},19:{title:"Вопрос \xabкак\xbb с 怎么",explanation:"怎么 (zěnme) означает \xabкак\xbb или спрашивает о способе действия.",examples:["Как пишется этот иероглиф?","Как добраться до вокзала?"]},20:{title:"Вопрос \xabпочему\xbb с 为什么",explanation:"为什么 (w\xe8ish\xe9nme) означает \xabпочему\xbb.",examples:["Почему ты расстроен?","Почему он не пришёл?"]},21:{title:"Вопрос \xabкакой\xbb с 哪个",explanation:"哪个 (nǎ ge) означает \xabкакой\xbb, \xabкоторый\xbb.",examples:["Какой тебе нравится?","Который из них твой?"]},22:{title:"Вопрос \xabсколько\xbb с 几",explanation:"几 (jǐ) спрашивает \xabсколько\xbb, когда ожидается небольшое число (до 10).",examples:["Сколько у тебя детей?","Который сейчас час?"]},23:{title:"Вопрос \xabсколько\xbb с 多少",explanation:"多少 (duōshǎo) спрашивает \xabсколько\xbb без ограничения по количеству.",examples:["Сколько это стоит?","Какой у тебя номер телефона?"]},24:{title:"Вопрос \xabкак\xbb о качестве с 怎么样",explanation:"怎么样 (zěnmey\xe0ng) спрашивает \xabкак?\xbb — для мнений, состояний или предложений.",examples:["Какая погода?","Как эта книга?"]},25:{title:"Вопрос о степени с 多",explanation:"多 (duō) перед прилагательным спрашивает о степени — насколько большой, сколько лет и т.д.",examples:["Сколько тебе лет?","Как далеко это?"]},26:{title:"Вопросы с 了吗",explanation:"了吗 спрашивает, совершилось ли уже ожидаемое действие.",examples:["Ты поел?","Он ушёл?"]},27:{title:"\xabТоже\xbb с 也",explanation:"也 (yě) означает \xabтоже\xbb. Ставится перед глаголом, никогда в конце.",examples:["Я тоже студент.","Он тоже любит смотреть фильмы."]},28:{title:"\xabВсе\xbb с 都",explanation:"都 (dōu) означает \xabвсе\xbb или \xabоба\xbb. Ставится перед глаголом и относится к подлежащему.",examples:["Мы все китайцы.","Они все пришли.","Мне всё это нравится."]},29:{title:"\xabСлишком\xbb с 太…了",explanation:"太…了 (t\xe0i…le) означает \xabслишком\xbb или \xabтак\xbb — выражает избыток или сильную эмоцию.",examples:["Отлично!","Это слишком дорого.","Сегодня слишком жарко."]},30:{title:"\xabНемного\xbb с 有点儿",explanation:"有点儿 (yǒudiǎnr) означает \xabнемного\xbb и обычно подразумевает что-то нежелательное.",examples:["Я немного устал.","Сегодня немного холодно."]},31:{title:"\xabСнова\xbb в будущем с 再",explanation:"再 (z\xe0i) означает \xabснова\xbb для будущих или гипотетических действий.",examples:["До свидания! (Увидимся снова)","Пожалуйста, скажите ещё раз."]},32:{title:"\xabЕщё\xbb / продолжение с 还",explanation:"还 (h\xe1i) означает \xabещё\xbb, указывая на продолжение действия или что-то дополнительное.",examples:["Он ещё спит.","Что ещё ты хочешь?"]},33:{title:"Умеренная оценка с 还 + прилагательное",explanation:"还 перед положительным прилагательным означает \xabсносно\xbb или \xabнеплохо\xbb — умеренно положительная оценка.",examples:["Вкус неплохой.","Ну, нормально."]},34:{title:"Местонахождение с 在",explanation:"在 (z\xe0i) как глагол означает \xabнаходиться в/на (каком-то месте)\xbb.",examples:["Он дома.","Мой телефон на столе."]},35:{title:"Действие в месте с 在",explanation:"在 перед словом места указывает, где происходит действие.",examples:["Я учусь в школе.","Они едят в ресторане."]},36:{title:"\xabХотеть\xbb с 想",explanation:"想 (xiǎng) означает \xabхотеть\xbb или \xabхотелось бы\xbb.",examples:["Я хочу выпить чая.","Куда ты хочешь пойти?","Я не хочу работать."]},37:{title:"Возможность с 能",explanation:"能 (n\xe9ng) выражает возможность или способность — \xabмочь\xbb в силу обстоятельств.",examples:["Ты можешь прийти?","Я сегодня не могу пойти."]},38:{title:"Приобретённый навык с 会",explanation:"会 (hu\xec) выражает \xabуметь\xbb — приобретённый навык, то, чему вы научились.",examples:["Ты умеешь говорить по-китайски?","Он умеет готовить.","Я не умею водить машину."]},39:{title:"Использование 对 с глаголами",explanation:"对 (du\xec) означает \xabпо отношению к\xbb — указывает на объект действия.",examples:["Он очень хорошо ко мне относится.","Учитель говорит ученикам."]},40:{title:"\xabНемного\xbb / \xabпопробовать\xbb с 一下",explanation:"一下 (y\xedxi\xe0) смягчает глагол — \xabчуть-чуть\xbb, \xabна секунду\xbb.",examples:["Подождите минутку.","Дайте мне посмотреть.","Попробуй."]},41:{title:"Результативный комплемент 完",explanation:"完 (w\xe1n) как результативный комплемент означает \xabзакончить делать\xbb.",examples:["Я доел.","Ты дочитал эту книгу?"]},42:{title:"\xabВместе\xbb с 一起",explanation:"一起 (y\xecqǐ) означает \xabвместе\xbb.",examples:["Давай поедим вместе.","Хочешь пойти вместе?"]},43:{title:"Завершённое действие с 了",explanation:"了 (le) после глагола обозначает, что действие завершено.",examples:["Я купил книгу.","Он ушёл.","Ты поел?"]},44:{title:"Новая ситуация с 了",explanation:"了 в конце предложения сигнализирует об изменении состояния — что-то стало иначе.",examples:["Пошёл дождь.","Я проголодался.","Пришла весна."]},45:{title:"Действие в процессе с 在",explanation:"在 или 正在 перед глаголом означает, что действие происходит прямо сейчас.",examples:["Он смотрит телевизор.","Я сейчас учу китайский.","Мама готовит."]},46:{title:"Смягчение с 吧",explanation:"吧 (ba) смягчает высказывание или делает его предложением — \xabдавай\xbb или \xabнаверное\xbb.",examples:["Пойдём.","Ну ладно.","Ты ведь учитель, да?"]},47:{title:"\xabКогда\xbb с 的时候",explanation:"的时候 (de sh\xedh\xf2u) означает \xabкогда\xbb или \xabв то время как\xbb.",examples:["Не разговаривай во время еды.","Когда идёт дождь, я дома."]},48:{title:"\xabВсё\xbb с 什么…都/也",explanation:"什么都 или 什么也 означает \xabвсё\xbb или \xabчто угодно\xbb (в зависимости от контекста).",examples:["Он ест всё.","Я ничего не хочу делать."]},49:{title:"Положение слов времени",explanation:"Слова времени могут стоять до или после подлежащего — оба варианта верны.",examples:["Я пойду завтра.","Вчера я не приходил."]},50:{title:"\xabПосле\xbb с 以后",explanation:"以后 (yǐh\xf2u) означает \xabпосле\xbb определённого времени или события.",examples:["После обеда пойдём гулять.","После трёх я свободен."]},51:{title:"\xabДо\xbb с 以前",explanation:"以前 (yǐqi\xe1n) означает \xabдо\xbb определённого времени или события.",examples:["До приезда в Китай я не говорил по-китайски.","Перед сном нужно чистить зубы."]},52:{title:"Структура даты",explanation:"Дата идёт от большего к меньшему: год, месяц, день.",examples:["1 января 2025 года","Какого числа твой день рождения?"]},53:{title:"Структура времени (часы)",explanation:"Время обозначается с 点 (diǎn) для часов и 分 (fēn) для минут.",examples:["Сейчас полчетвёртого.","Мой урок начинается в 8 часов."]},54:{title:"Счётное слово 个",explanation:"个 (g\xe8) — самое распространённое счётное слово. Используйте его, если не знаете специального счётного слова.",examples:["один человек","три яблока","сколько студентов"]},55:{title:"Возраст с 岁",explanation:"岁 (su\xec) — счётное слово для возраста, глагол не нужен.",examples:["Мне двадцать лет.","Его дочери пять лет."]},56:{title:"Счёт денег",explanation:"块 (ku\xe0i) — разговорное слово для юаней, 毛 (m\xe1o) — для цзяо (десятых юаня).",examples:["десять юаней","три с половиной юаня"]},57:{title:"Порядковые числительные с 第",explanation:"第 (d\xec) превращает число в порядковое — первый, второй, третий и т.д.",examples:["первый","третий человек","Это мой первый раз в Китае."]},58:{title:"\xabНесколько\xbb с 一些",explanation:"一些 (y\xecxiē) означает \xabнесколько\xbb или \xabнемного\xbb.",examples:["У меня есть несколько вопросов.","Дайте мне немного воды."]},59:{title:"Разрешение с 可以",explanation:"可以 (kěyǐ) выражает разрешение (\xabможно\xbb) или возможность. Отрицание — 不可以 (нельзя).",examples:["Можно мне войти?","Здесь нельзя курить."]},60:{title:"Сравнение с 比",explanation:"比 (bǐ) сравнивает две вещи. После 比 прилагательное не может использовать 很.",examples:["Он выше меня.","Сегодня холоднее, чем вчера.","Китайский сложнее английского."]},61:{title:"\xabТакой же, как\xbb с 一样",explanation:"一样 (y\xedy\xe0ng) означает \xabодинаковый\xbb. Используйте 跟 или 和 для связи сравниваемых объектов.",examples:["Я такого же роста, как ты.","Этот такой же, как тот.","Его телефон такой же, как мой."]},62:{title:"Превосходная степень с 最",explanation:"最 (zu\xec) означает \xabсамый\xbb. Ставится непосредственно перед прилагательным или глаголом.",examples:["Она самая красивая.","Больше всего я люблю китайскую еду.","Этот самый дешёвый."]},63:{title:"\xabЕщё более\xbb с 更",explanation:"更 (g\xe8ng) означает \xabещё более\xbb. Подчёркивает более высокую степень, чем ожидалось.",examples:["Завтра будет ещё холоднее.","Я хочу найти ещё лучшую работу.","Он ещё выше меня."]},64:{title:"\xabЧуть больше\xbb с 一点儿",explanation:"一点儿 (y\xecdiǎnr) после сравнения означает \xabчуть-чуть больше\xbb. Часто используется с 比 или в просьбах.",examples:["Пожалуйста, говорите чуть медленнее.","Этот чуть больше того.","Подешевле, пожалуйста."]},65:{title:"Причина и следствие с 因为…所以",explanation:"因为 (yīnw\xe8i) означает \xabпотому что\xbb, а 所以 (suǒyǐ) — \xabпоэтому\xbb. Можно использовать одно или оба.",examples:["Из-за дождя я не пошёл.","Он заболел, поэтому не пришёл на занятия.","Я устал, поэтому хочу отдохнуть."]},66:{title:"Противопоставление с 虽然…但是",explanation:"虽然 (suīr\xe1n) означает \xabхотя\xbb, а 但是 (d\xe0nsh\xec) — \xabно\xbb. Контраст идёт вторым.",examples:["Хотя дорого, но вкусно.","Хотя он занят, он всё равно пришёл.","Хотя трудно, я хочу попробовать."]},67:{title:"\xabКроме\xbb с 除了…以外",explanation:"除了…以外 (ch\xfale…yǐw\xe0i) означает \xabкроме\xbb или \xabза исключением\xbb. 都 исключает, 也/还 включает.",examples:["Кроме него, мы все пошли.","Кроме китайского, она ещё говорит по-английски."]},68:{title:"\xabИли\xbb с 还是 и 或者",explanation:"还是 (h\xe1ishi) используется в вопросах с выбором. 或者 (hu\xf2zhě) — в утверждениях.",examples:["Тебе чай или кофе?","Завтра или послезавтра — всё равно.","Ты едешь на автобусе или на метро?"]},69:{title:"\xabНе только…но и\xbb с 不但…而且",explanation:"不但 (b\xfad\xe0n) означает \xabне только\xbb, а 而且 (\xe9rqiě) — \xabно и\xbb. Б — более сильный аргумент.",examples:["Он не только говорит по-китайски, но и говорит очень хорошо.","Это место не только красивое, но и очень тихое."]},70:{title:"\xabУже\xbb с 已经…了",explanation:"已经 (yǐjīng) означает \xabуже\xbb. 了 в конце подтверждает изменение состояния.",examples:["Я уже поел.","Он уже ушёл.","Фильм уже начался."]},71:{title:"\xabТолько что\xbb с 刚 и 刚才",explanation:"刚 (gāng) означает \xabтолько что\xbb и ставится перед глаголом. 刚才 (gāngc\xe1i) означает \xabтолько что\xbb и может стоять перед подлежащим или глаголом.",examples:["Я только что приехал.","Он только что тебе звонил.","Она только что поела."]},72:{title:"\xabНаконец\xbb с 终于",explanation:"终于 (zhōngy\xfa) означает \xabнаконец\xbb. Подразумевает долгое ожидание.",examples:["Ты наконец пришёл!","Я наконец нашёл это.","Дождь наконец прекратился."]},73:{title:"\xabЧасто\xbb с 常常 и 经常",explanation:"常常 (ch\xe1ngch\xe1ng) и 经常 (jīngch\xe1ng) оба означают \xabчасто\xbb. В большинстве случаев взаимозаменяемы.",examples:["Я часто хожу в тот ресторан.","Он часто опаздывает.","Она часто мне помогает."]},74:{title:"\xabВсегда\xbb / \xabвсё время\xbb с 一直",explanation:"一直 (y\xeczh\xed) означает \xabвсегда\xbb или \xabнепрерывно\xbb — действие, которое продолжается без остановки.",examples:["Я всё это время тебя ждал.","Он всегда жил в Пекине.","Она всегда была трудолюбивой."]},75:{title:"\xabВдруг\xbb с 突然",explanation:"突然 (tūr\xe1n) означает \xabвдруг\xbb. Может стоять перед подлежащим или глаголом.",examples:["Он вдруг замолчал.","Вдруг пошёл дождь.","Она вдруг засмеялась."]},76:{title:"\xabСейчас же\xbb с 马上",explanation:"马上 (mǎsh\xe0ng) означает \xabсейчас же\xbb или \xabнемедленно\xbb.",examples:["Я сейчас приду.","Фильм вот-вот начнётся.","Он сейчас вернётся."]},77:{title:"Результативный комплемент 到",explanation:"到 (d\xe0o) как результативный комплемент означает, что действие успешно достигло цели — \xabнайти\xbb, \xabдостичь\xbb, \xabдо\xbb.",examples:["Я нашёл это.","Ты слышал?","Я его увидел."]},78:{title:"Результативный комплемент 好",explanation:"好 (hǎo) как результативный комплемент означает, что действие выполнено должным образом — \xabготово\xbb, \xabсделано\xbb.",examples:["Еда готова.","Ты готов?","Домашняя работа сделана."]},79:{title:"Комплемент направления 来/去",explanation:"来 (l\xe1i) указывает движение к говорящему; 去 (q\xf9) — от говорящего. Они следуют за основным глаголом.",examples:["Он подбежал ко мне.","Пожалуйста, входите.","Он вышел."]},80:{title:"Потенциальный комплемент с 得/不",explanation:"Глагол + 得 + комплемент означает \xabможно сделать\xbb. Глагол + 不 + комплемент означает \xabне получится\xbb.",examples:["Я вижу.","Я не понимаю на слух.","Столько можно доесть?"]},81:{title:"Комплемент степени с 得",explanation:"得 (de) после глагола вводит описание того, как выполнено действие — его способ или результат.",examples:["Он говорит очень хорошо.","Она бегает очень быстро.","Ты пишешь слишком медленно."]},82:{title:"Конструкция с 把",explanation:"把 (bǎ) выносит дополнение перед глаголом, чтобы подчеркнуть, что с ним происходит. Глагол должен иметь результат или направление.",examples:["Пожалуйста, закройте дверь.","Он положил книгу на стол.","Я сделал домашнее задание."]},83:{title:"Страдательный залог с 被",explanation:"被 (b\xe8i) обозначает страдательный залог. Подлежащее испытывает действие. Часто подразумевается что-то нежелательное.",examples:["Мой телефон украли.","Торт съел он.","Ту книгу кто-то взял."]},84:{title:"\xabПозволять / заставлять\xbb с 让",explanation:"让 (r\xe0ng) означает \xabпозволять\xbb или \xabзаставлять кого-то делать что-то\xbb.",examples:["Мама заставляет меня учиться.","Дай мне подумать.","Учитель не разрешает нам разговаривать."]},85:{title:"\xabОт…до\xbb с 从…到",explanation:"从 (c\xf3ng) означает \xabот\xbb, а 到 (d\xe0o) — \xabдо\xbb. Используется для временных и пространственных диапазонов.",examples:["Отсюда до школы близко.","С утра до вечера.","Я еду поездом из Пекина в Шанхай."]},86:{title:"\xabВ направлении\xbb с 向 и 往",explanation:"向 (xi\xe0ng) и 往 (wǎng) оба означают \xabв направлении\xbb. 往 чаще для физического направления; 向 также для абстрактных целей.",examples:["Идите прямо.","Поверните налево.","Он пошёл ко мне."]},87:{title:"Двойное 了: продолжающееся действие",explanation:"Два 了 — один после глагола и один в конце — означают, что действие началось в прошлом и всё ещё продолжается.",examples:["Я учу китайский уже три года.","Он ждёт уже два часа.","Мы живём здесь уже пять лет."]},88:{title:"Выражение длительности",explanation:"Длительность ставится после глагола. Если есть дополнение, глагол либо повторяется, либо перед дополнением добавляется 的.",examples:["Я учусь по два часа каждый день.","Он проспал восемь часов.","Я читал час."]},89:{title:"Выражение частоты с 每",explanation:"每 (měi) означает \xabкаждый\xbb. 都 часто следует за ним для усиления — \xabвсегда\xbb, \xabкаждый раз\xbb.",examples:["Я занимаюсь спортом каждый день.","Он ходит туда каждую неделю.","Все пришли."]},90:{title:"\xabОдновременно\xbb с 一边…一边",explanation:"一边…一边 (y\xecbiān…y\xecbiān) означает выполнение двух действий одновременно.",examples:["Он ест и смотрит телевизор.","Она идёт и разговаривает по телефону.","Я слушаю музыку и учусь."]},91:{title:"Выражение цели с 为了",explanation:"为了 (w\xe8ile) означает \xabдля того чтобы\xbb. Указывает цель или причину действия.",examples:["Чтобы выучить китайский, я приехал в Китай.","Он занимается ради экзамена.","Ради здоровья нужно больше заниматься спортом."]},92:{title:"\xabЗависит от\xbb с 看",explanation:"看 (k\xe0n) может означать \xabзависит от\xbb. После 看 следует то, от чего зависит результат.",examples:["Зависит от погоды.","Зависит от того, куда ты хочешь поехать.","Пойду или нет — зависит от обстоятельств."]},93:{title:"Продолжающееся состояние с 着",explanation:"着 (zhe) указывает на состояние, возникшее в результате действия — действие произошло, и состояние сохраняется.",examples:["Дверь открыта.","Он стоит.","На стене висит картина."]}}}}]);